from __future__ import annotations

import json
import uuid
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

from vault.paths import FACES_DIR, FACES_INDEX, INDEX_PATH, ensure_data_dir


def _now() -> str:
    return datetime.now(timezone.utc).isoformat()


def _load(path: Path, default: dict[str, Any]) -> dict[str, Any]:
    ensure_data_dir()
    if not path.exists():
        return default
    return json.loads(path.read_text(encoding="utf-8"))


def _save(path: Path, payload: dict[str, Any]) -> None:
    ensure_data_dir()
    path.write_text(json.dumps(payload, indent=2), encoding="utf-8")


def list_faces() -> list[dict[str, Any]]:
    return _load(FACES_INDEX, {"faces": []}).get("faces", [])


def get_face(face_id: str) -> dict[str, Any] | None:
    for face in list_faces():
        if face["id"] == face_id:
            return face
    return None


def save_face(name: str, image_bytes: bytes) -> dict[str, Any]:
    faces = list_faces()
    face_id = str(uuid.uuid4())
    folder = FACES_DIR / face_id
    folder.mkdir(parents=True, exist_ok=True)
    image_path = folder / "enroll_0.jpg"
    image_path.write_bytes(image_bytes)
    record = {
        "id": face_id,
        "name": name.strip() or "Owner",
        "created_at": _now(),
        "images": [str(image_path)],
    }
    faces.append(record)
    _save(FACES_INDEX, {"faces": faces})
    return record


def add_face_image(face_id: str, image_bytes: bytes) -> dict[str, Any]:
    faces = list_faces()
    for face in faces:
        if face["id"] != face_id:
            continue
        folder = FACES_DIR / face_id
        folder.mkdir(parents=True, exist_ok=True)
        index = len(face.get("images", []))
        image_path = folder / f"enroll_{index}.jpg"
        image_path.write_bytes(image_bytes)
        face.setdefault("images", []).append(str(image_path))
        _save(FACES_INDEX, {"faces": faces})
        return face
    raise KeyError(f"Unknown Face ID: {face_id}")


def list_items() -> list[dict[str, Any]]:
    return _load(INDEX_PATH, {"items": []}).get("items", [])


def upsert_item(record: dict[str, Any]) -> dict[str, Any]:
    items = list_items()
    for i, existing in enumerate(items):
        if existing["id"] == record["id"] or existing.get("original_path") == record.get(
            "original_path"
        ):
            items[i] = record
            _save(INDEX_PATH, {"items": items})
            return record
    if "id" not in record:
        record["id"] = str(uuid.uuid4())
    items.append(record)
    _save(INDEX_PATH, {"items": items})
    return record


def get_item(item_id: str) -> dict[str, Any] | None:
    for item in list_items():
        if item["id"] == item_id:
            return item
    return None

from pathlib import Path

import streamlit as st

from vault.locker import LockError, lock_path
from vault.picker import pick_from_disk
from vault.store import list_faces
from vault.ui import require_api_key, require_face

require_api_key()
faces = require_face()

st.markdown(
    "Choose a real path on this computer. Face Vault encrypts it in place: "
    "the original is replaced by a `.facevault` lock file in the same folder."
)

kind = st.segmented_control(
    "What to lock",
    options=["file", "folder"],
    default="file",
    key="lock_kind",
)

path_row = st.container(horizontal=True, vertical_alignment="bottom")
path_value = path_row.text_input(
    "Path on disk",
    key="lock_path",
    placeholder=r"C:\Users\you\Documents\secret.pdf",
)
if path_row.button("Browse", icon=":material/folder_open:"):
    try:
        chosen = pick_from_disk(kind or "file")
    except Exception as exc:
        st.error(f"Could not open a file picker: {exc}", title="Browse failed")
    else:
        if chosen:
            st.session_state.lock_path = chosen
            st.rerun()

face_labels = {face["id"]: face["name"] for face in faces}
face_id = st.selectbox(
    "Face ID that can unlock this item",
    options=list(face_labels),
    format_func=lambda value: face_labels[value],
)

uploaded = st.file_uploader(
    "Or drop a file here, then confirm its original disk path above",
    accept_multiple_files=False,
    help="The browser cannot see the original path. Face Vault still locks the path you enter, not a copied upload.",
)

if uploaded is not None and not st.session_state.lock_path:
    st.warning(
        "Dropping a file only identifies it. Paste or browse the original path so the copy on disk can be locked.",
        title="Disk path required",
    )

st.warning(
    "Locking is immediate and destructive: the readable original is removed after encryption succeeds.",
    title="This encrypts the original on disk",
)

if st.button("Lock now", type="primary", icon=":material/lock:"):
    target = (st.session_state.lock_path or "").strip()
    if not target:
        st.error("Choose a file or folder path first.", title="Nothing selected")
    elif not Path(target).exists():
        st.error(f"No file or folder exists at `{target}`.", title="Path not found")
    else:
        with st.spinner("Encrypting the original on disk…"):
            try:
                record = lock_path(target, face_id)
            except LockError as exc:
                st.error(str(exc), title="Could not lock")
            except Exception as exc:
                st.error(str(exc), title="Lock failed")
            else:
                st.session_state.lock_path = ""
                st.success(
                    f"Locked **{record['original_name']}**. "
                    f"The original is gone; the lock file is `{record['locked_path']}`."
                )

