from __future__ import annotations

import json
import re
from pathlib import Path
from typing import Any

import numpy as np
from groq import Groq

from vault.groq_face import get_api_key, get_model
from vault.paths import RAG_INDEX_PATH, ensure_data_dir
from vault.store import list_faces, list_items
from vault.vision import cosine, decode_image, detect_faces, face_embedding, largest_face


def _text_embedding(text: str) -> np.ndarray:
    vec = np.zeros(128, dtype=np.float32)
    tokens = re.findall(r"[a-z0-9]+", text.lower())
    if not tokens:
        return vec
    for token in tokens:
        vec[hash(token) % 128] += 1.0
    norm = np.linalg.norm(vec)
    if norm:
        vec /= norm
    return vec


def _docs() -> list[dict[str, Any]]:
    docs: list[dict[str, Any]] = []
    for face in list_faces():
        text = (
            f"Face ID name={face.get('name')} id={face.get('id')} "
            f"photos={len(face.get('images') or [])} created={face.get('created_at')}"
        )
        docs.append(
            {
                "id": f"face:{face['id']}",
                "kind": "face",
                "face_id": face["id"],
                "text": text,
                "images": face.get("images") or [],
            }
        )
    for item in list_items():
        text = (
            f"Vault item name={item.get('original_name')} kind={item.get('kind')} "
            f"status={item.get('status')} original_path={item.get('original_path')} "
            f"locked_path={item.get('locked_path')} face_id={item.get('face_id')}"
        )
        docs.append(
            {
                "id": f"item:{item.get('id')}",
                "kind": "item",
                "face_id": item.get("face_id"),
                "text": text,
                "images": [],
            }
        )
    docs.append(
        {
            "id": "guide:opencv",
            "kind": "guide",
            "face_id": None,
            "text": (
                "Face Vault uses OpenCV live webcam capture and YuNet/Haar face detection. "
                "A Face ID must be enrolled before locking. Locking encrypts the original "
                "file or folder on disk into a .facevault file. Unlock requires a live "
                "detected face that RAG matches to the enrolled Face ID."
            ),
            "images": [],
        }
    )
    return docs


def rebuild_index() -> list[dict[str, Any]]:
    ensure_data_dir()
    payload = []
    for doc in _docs():
        row = dict(doc)
        row["embedding"] = _text_embedding(doc["text"]).tolist()
        payload.append(row)
    RAG_INDEX_PATH.write_text(json.dumps({"docs": payload}, indent=2), encoding="utf-8")
    return payload


def _load_index() -> list[dict[str, Any]]:
    if not RAG_INDEX_PATH.exists():
        return rebuild_index()
    return json.loads(RAG_INDEX_PATH.read_text(encoding="utf-8")).get("docs", [])


def retrieve_text(query: str, k: int = 5) -> list[dict[str, Any]]:
    docs = _load_index()
    if not docs:
        docs = rebuild_index()
    q = _text_embedding(query)
    ranked = sorted(
        docs,
        key=lambda doc: cosine(q, np.array(doc.get("embedding") or [], dtype=np.float32)),
        reverse=True,
    )
    return ranked[:k]


def retrieve_faces(live_image: bytes, k: int = 3) -> list[dict[str, Any]]:
    frame = decode_image(live_image)
    faces = detect_faces(frame)
    chosen = largest_face(faces)
    crop = chosen.crop if chosen is not None else frame
    live_vec = face_embedding(crop)
    hits = []
    for face in list_faces():
        best = -1.0
        best_path = None
        for path in face.get("images") or []:
            if not Path(path).exists():
                continue
            enrolled = decode_image(Path(path).read_bytes())
            enrolled_faces = detect_faces(enrolled)
            enrolled_crop = enrolled_faces[0].crop if enrolled_faces else enrolled
            score = cosine(live_vec, face_embedding(enrolled_crop))
            if score > best:
                best = score
                best_path = path
        hits.append({"face": face, "score": best, "image": best_path})
    hits.sort(key=lambda row: row["score"], reverse=True)
    return [row for row in hits if row["score"] >= 0][:k]


def answer(query: str) -> str:
    rebuild_index()
    retrieved = retrieve_text(query, k=6)
    context = "\n".join(f"- {doc['text']}" for doc in retrieved) or "No vault records yet."
    api_key = get_api_key()
    if not api_key:
        return "Retrieved vault context:\n" + context
    try:
        client = Groq(api_key=api_key, base_url="https://api.groq.com/openai/v1")
        completion = client.chat.completions.create(
            model=get_model(),
            messages=[
                {
                    "role": "system",
                    "content": (
                        "You are Face Vault's RAG assistant. Answer only from the retrieved "
                        "context about Face IDs, locked files, and how OpenCV unlocking works."
                    ),
                },
                {
                    "role": "user",
                    "content": f"Context:\n{context}\n\nQuestion: {query}",
                },
            ],
            temperature=0.2,
            max_completion_tokens=400,
        )
        return completion.choices[0].message.content or context
    except Exception:
        return (
            "Groq is unavailable, so here is the retrieved local context:\n" + context
        )

from __future__ import annotations

import os

DEFAULT_MODEL = "qwen/qwen3.8-27b"


def get_api_key() -> str | None:
    key = os.environ.get("GROQ_API_KEY", "").strip()
    if key:
        return key
    try:
        import streamlit as st

        value = st.secrets.get("GROQ_API_KEY")
        if value:
            return str(value).strip()
    except Exception:
        return None
    return None


def get_model() -> str:
    model = os.environ.get("GROQ_MODEL", "").strip()
    if model:
        return model
    try:
        import streamlit as st

        value = st.secrets.get("GROQ_MODEL")
        if value:
            return str(value).strip()
    except Exception:
        pass
    return DEFAULT_MODEL
